export type GuideEntry={id:string;title:string;purpose:string;href?:string;location?:string;steps:string[];notes?:string[];topics?:string[]};

export const guideLastUpdated = '2026-11-17';
export type GuidePage=GuideEntry&{features:string[];actions:{title:string;description:string}[]};

export const guidePages:GuidePage[]=[
 {"id":"ai-analyst","title":"AI Social Media Analyst","purpose":"Interpret recorded Facebook and Instagram performance, review supported content tests and learn from their results.","href":"/workspace/analyst","location":"Sidebar / AI & Content / AI Social Media Analyst","features":["Optional Gemini recommendations using the existing cache and shared allowance","Supporting statistics, local post examples, comparison dates, sample sizes and limitations","Singapore community-care content opportunities and anonymised caption rewriting","Staff-approved Draft plans and saved experiment criteria","Follow-up evaluation against the original historical baseline","Selected Executive Finding with server-recalculated evidence","Separate optional Gemini interpretation of that selected evidence","Statement-level AI screening; calculated findings stay separate from hypotheses and suggested experiments","High and low matched-post examples show account, date, recorded metrics and original links","Separate supported Facebook Views and Instagram Reach trend explanations"],"actions":[{"title":"Apply Filters / Refresh Analysis","description":"Choose platform, configured account, brand and date range, then calculate the matching evidence. Refresh reloads current records."},{"title":"Generate Gemini Recommendations","description":"Request concise interpretation of prequalified findings. Exact statistics stay calculated. Gemini availability errors leave the findings usable."},{"title":"Add to Content Planner / Save Approved Draft","description":"Review title and planned date before approving a Draft. For supported experiments, also review the end date, minimum posts and staff-set target. Nothing is published automatically."},{"title":"Generate Content Suggestions","description":"Request topics, publicity ideas, engagement questions, active-ageing ideas, improved captions or alternatives. Suggestions are proposed content, not observed audience facts."},{"title":"Link published result posts / Save Result Links & Evaluate","description":"Select the complete trial series and confirm. The analyst evaluates eligible recorded outcomes without changing post statistics."},{"title":"Ask Gemini About This Finding","description":"Request deeper interpretation using the existing Gemini provider, evidence validation, cache and allowance. Only anonymised metrics are sent; recorded facts stay separate from hypotheses."},{"title":"Supporting Data & Limitations / Inspect Supporting Evidence","description":"Inspect calculated findings, exact dates, comparison groups, sample sizes and source records. Displayed numbers and dates come from the application, not Gemini. A screened AI implication remains a hypothesis."},{"title":"I checked the supporting statistics, dates and source posts.","description":"Confirm this evidence review separately from final plan approval. Review or edit Reviewed Next Step and success criteria before Save Approved Draft. Source changes require Refresh Analysis and another review."}],"steps":["From Executive Performance Intelligence, choose Explore with AI Social Media Analyst. Review Selected Executive Finding, its metrics, dates and supporting samples.","Open AI Social Media Analyst. Calculated findings load automatically; set filters and choose Apply Filters to narrow the question.","Read the performance summary, then the observation, supporting statistics, examples, period, sample and limitations on each recommendation. Open a source example to review the record and original link.","Optionally choose Generate Gemini Recommendations. Gemini can add a suggested action and implication, but cannot supply new statistics or determine best posting times without evidence.","For an interaction-based recommendation, choose Add to Content Planner. Inspect supporting evidence, review or edit Reviewed Next Step, confirm the statistics, dates and source posts, set the future trial window and success criteria, then approve Save Approved Draft. Visibility-only findings link to their source measurements rather than creating an interaction-based experiment.","For Content Opportunities, select request, platform, topic and call to action. Caption improvement or alternatives require anonymised English text and privacy confirmation. Replace names with [participant], remove contacts and identifying details, and never paste an unreviewed saved caption. Review the generated text before saving it as a Draft.","Publish through the normal staff workflow and record actual posts and metrics separately. In Suggested Experiments & Follow-Up, link the trial posts and confirm that the full series is included. Refresh to see the latest calculated result."],"notes":["Performance prompts exclude raw post titles, stored captions, notes, URLs and custom account, brand and topic labels. Source examples stay local to the authorised workspace. Identifying-text checks on manually submitted captions are conservative and do not replace staff privacy review. This caption tool accepts anonymised English; the existing AI Content Studio retains other writing workflows.","Comparisons match platform, account, month and recorded measurement basis. Format/topic suggestions require three posts per side and a directional mean difference; topic comparisons also match format. Each format or topic uses its latest eligible matched cohort and shows that cohort?s exact comparison window; this does not claim consistent performance across months. Trend comparisons require fully measured same-account/format groups with at least three posts per reporting window. They do not establish causes or audience demographics. Missing readings stay unavailable and Facebook Views are not added to Instagram Reach.","Experiment baselines, success criteria and publication windows are fixed when saved. Editing a Content Planner item later does not change those original experiment criteria. Follow-up requires published posts from the saved account, brand and format, matching the saved measurement basis, with a known metrics update at least seven days after posting.","Pending means the window is still open. Insufficient data means it ended without enough eligible measured posts. Criteria met / Criteria not met compares the recorded mean with the staff-approved target; neither demonstrates causal impact or statistical significance. Select the entire trial series to avoid cherry-picking.","A content-opportunity draft without a measured baseline is proposed content, not an experiment with a claimed success result. All generated content needs staff fact, consent and accessibility review. No external accounts are changed and nothing is published automatically.","The Evidence Scope card shows the dates and measurement coverage used by the recommendations. KPI charts are maintained in Social Media Analytics; use Open the detailed Analytics Workspace to inspect them. Content Opportunities remains a contextual, reviewed writing action; AI Content Studio is the primary communications editor.","Refresh Analysis if source data changed. An expired or no-longer-supported finding is not silently reused. Changing Analyst filters can invalidate the selected finding. Standard Analyst recommendations, writing, approved planning and follow-up remain unchanged.","Fresh and cached Gemini recommendations are screened again. Unsupported numbers or dates, invented references, mismatched platforms/accounts, contradictory directions and invalid cohorts are withheld. The displayed observation is rebuilt from the current calculated finding. Screening does not prove every qualitative interpretation true.","Evidence revisions include selected and baseline records plus observation metadata. Baseline edits invalidate old interpretation and planner requests. Other-tab workspace changes refresh the Analyst.","Facebook Views and Instagram Reach are never combined. Visibility trend explanations need complete recorded coverage within the same account and format in both comparable windows. Accumulated observations do not establish equal-age or causal effects."],"topics":["Gemini","AI analyst","recommendations","supporting data","experiments","follow up","caption","privacy","Add to Content Planner","success metric"]},
 {"id":"dashboard","title":"Executive Dashboard","purpose":"Review essential management results, key changes and the next decisions.","href":"/workspace","features":["Overall Performance with recorded interactions, distinct Facebook Views and Instagram Reach, coverage and prior-period changes","Consistent neutral comparison cards with aligned metrics, measured-post averages and prior-period changes","One platform-selectable monthly brand trend; gaps remain unavailable","Readable neutral platform cards with aligned metrics, measurement coverage and a detailed Analytics link at the bottom of each card","One Executive Performance Intelligence section: What Improved, What Declined, What Influenced Performance and What Should We Do Next","Prioritised, deduplicated calculated findings with sample sizes, benchmark types and expandable evidence","Custom Range, Month-on-Month, Quarter-on-Quarter and Year-on-Year comparisons using the exact selected dates"],"actions":[{"title":"Explore Social Media Analytics","description":"Open the detailed Analytics Workspace for trends, comparisons, source records and data quality."},{"title":"Top Hits Intelligence","description":"Use the sidebar to open the complete rankings and recurring-feature evidence."},{"title":"Quick Actions","description":"Open Social Media Posts, Followers, Workvivo, Public Site Manager or Content Planner. These are contextual links to the original workflows. Generate Monthly Report is available in the page header."},{"title":"Explore Brand Details","description":"Open Brand Details in Social Media Analytics. The reporting dates, platform, account and brand are carried across; adjust analytical filters there as needed."},{"title":"Comparison Platform","description":"Switch the management brand trend between Facebook and Instagram without mixing visibility metrics. When the main platform filter is set, this selector follows it."},{"title":"Executive Performance Intelligence","description":"Read the highest-priority supported findings and two default actions. Expand more findings, supporting metrics or sources when useful."},{"title":"Custom Range / Month-on-Month / Quarter-on-Quarter / Year-on-Year","description":"Custom uses the existing previous comparable interval. Other modes shift the exact selected dates by 1, 3 or 12 months; choose a full month or quarter for a complete-period comparison. Overlapping windows are withheld."},{"title":"Explore with AI Social Media Analyst","description":"Open the selected finding and its filters in the existing Analyst. The server recalculates its metrics; no client-supplied figures are trusted."}],"steps":["Expand Reporting Period & Filters to choose platform, account, brand, location and dates. Every dashboard section follows this scope. Selecting one account or brand can exclude the other comparison side.","Review Overall Performance, platform visibility readings and coverage. Facebook Views and Instagram Reach remain separate.","Compare GLOW and SEEN activity, recorded interactions and average per measured post. Read prior-period dates and coverage before interpreting a change.","Read Executive Performance Intelligence. Review the displayed dates, benchmark type, samples and limitations before acting. Expand evidence and source links for supporting records.","Use Comparison Platform under Performance Trends to see the monthly brand average. Open Monthly values and coverage for exact readings.","Choose Explore Brand Details for the detailed tables in Social Media Analytics. Read What Should We Do Next and use the existing planning or reporting tools."],"notes":["The sidebar navigation scrolls independently of the dashboard. Use a mouse wheel, touchpad or touch; focus Primary navigation and use arrow keys, or Tab through links to bring each into view. Settings remains near the bottom. On very short screens or high zoom, scroll the sidebar itself to reach its footer. Open Settings > User Guide for these instructions; there is no separate guide in Administration.","Sidebar links use the same readable text style. Green text and a tinted background identify the active destination; submenu indentation shows hierarchy. Use the arrow beside a group to expand or collapse it.","Brand Comparison is integrated here. Old /workspace/compare and /compare links redirect to the brand section. There is no separate Brand Comparison sidebar page.","Brand monthly averages have one primary graph here. Detailed brand/format/basis, topic, location and account tables live in Social Media Analytics under Brand Details. Followers owns brand account histories; Top Hits owns full rankings.","Missing data stays unavailable; measured zero stays zero. Raw brand averages describe the recorded platform/account mix. Audience, paid promotion and measurement timing may differ.","The prior period is the previous calendar month for a full selected month, matching elapsed days for month-to-date, or the previous equal-length interval for other ranges. Saved reports are unchanged.","The former Key Management Insights, executive Gemini briefing and separate Recommended Next Actions panel are consolidated here. The Executive Dashboard no longer makes an independent AI request.","Totals and per-post changes for the same cohort have one primary display. Internal history is not an external industry benchmark. Small movements may be withheld by stated review thresholds; no statistical significance is claimed.","No records, missing measurements, insufficient history, unchanged results and small movements have distinct compact availability messages. Missing values are never zero-filled.","Account-wide follower findings are omitted for location filters. Workvivo uses separate metrics and logging coverage, never external engagement totals."],"topics":["dashboard","overview","management","KPIs","comparisons","quick actions"]},
 {"id":"analytical-dashboards","title":"Analytics Workspace","purpose":"Understand recorded results, compare like with like and identify practical next actions.","href":"/workspace/analytics","location":"Social Media Analytics","features":["Growth Analysis uses published website and Excel-imported records without requiring Reach. Views and Reach are optional, separate readings; missing values are never zero.","Performance Comparisons with account comparisons and platform contribution","Post Performance with matched peers, sorting and source-record drill-down","Content Patterns with format/topic matching and recorded posting frequency","Audience & Account Growth using non-inferred, non-conflicting follower history","Data Quality with missing core metrics, import completeness and age review","Platform, account, brand and date filters shared by all views","Brand Details: retained platform/format/basis, topic, location and account tables for all selected brands","Public Account Benchmarks: one expandable source-coverage comparison in Performance Comparisons"],"actions":[{"title":"Growth Analysis & Detailed Benchmarks","description":"Choose Month-on-Month, Quarter-on-Quarter or Year-on-Year. Inspect exact dates, measured sample sizes and coverage. Incompatible components, accounts, ages or partial windows withhold unsupported changes. Percentages require a positive baseline."},{"title":"Dashboard buttons","description":"Switch between Performance Comparisons, Post Performance, Content Patterns, Audience & Account Growth and Data Quality. Platform Comparison preserves the earlier summary and AI analysis."},{"title":"Filters / Reset Filters","description":"Select platform, account, brand and date range. Reset returns to the full available history. These filters apply to all analytical views."},{"title":"Export This View (CSV)","description":"Download the filtered view with its reporting window, coverage and comparison context. Post exports include all filtered rows, not just the current page. Blank cells represent unavailable results; zeros remain zero."},{"title":"Refresh Data","description":"Request fresh workspace records. The received time can reflect cached data until refreshed; it is different from the latest metrics update."},{"title":"Post title / Original post link","description":"Open saved post details or its original social post when a valid URL exists."},{"title":"Quick Update Metrics / Edit Details","description":"Open the existing record workflow to correct measurements or metadata. Metric updates require review and retain previous readings."},{"title":"Sort By / Ascending / Descending / Posts Needing Review","description":"Sort post results or show missing measurements and posts below 75% of a supported peer average. Rate sorting is available only within one selected platform."},{"title":"Brand Details","description":"Explore detailed brand cohorts and export their filtered source records. The brand summary and trend stay on the Executive Dashboard."},{"title":"View Executive Performance Intelligence","description":"Use the contextual link on the platform or Workvivo page for central management findings. The Analytics Workspace remains the detailed exploration tool."},{"title":"Public Account Benchmarks","description":"Expand to check source readiness. Select dates matching completed inventory reviews, a Configuration-linked Tzu Chi public account and an external account. Inspect samples, coverage, matching public components and actual measurement age, and expand original-source evidence. Private complete engagement is never used as the public baseline."}],"steps":["Open Social Media Analytics and choose an analytical dashboard. Use Platform, Account, Brand and Date Range to define the question. Choose Brand Details for retained brand cohorts.","Read the selected period, previous equal-length period, sample sizes and measurement coverage before interpreting charts. Facebook Views and Instagram Reach stay separate.","Use Post Performance to review rankings and comparable peer ratios. At least three other posts from the same platform, account, format, calendar month and measurement basis are required. Click a post title for details.","Use Content Patterns to compare formats and topics. Matched comparisons require three posts per side. Frequency associations require four full, measured calendar months within the same account and measurement definition.","Use Audience & Account Growth for verified saved record dates and gaps. Use Data Quality to review missing core metrics, unknown timestamps and records older than the 30-day review policy.","Read What happened, What the figures suggest, What staff should investigate and What to consider testing next below the charts. Export the view or update the source record as needed.","Choose Brand Details for the retained detailed comparisons. Expand topic, account or location tables as needed; use Post Performance for original records."],"notes":["The Executive Dashboard is the management summary. Performance Comparisons owns the monthly interaction chart. Audience & Account Growth retains actual baseline dates, unusual-change evidence and separate Facebook Views / Instagram Reach charts; its follower-history link opens Followers instead of copying that graph. Platform Comparison retains the detailed Facebook/Instagram comparison cards and winner badges formerly on the Executive Dashboard. It no longer repeats separate overall KPI cards, full rankings or an AI summary.","Analytical explanations are deterministic. They do not invent causes or use AI to calculate statistics. AI remains in the existing platform summary and analyst.","Recorded interactions use the supplied total, otherwise the sum of explicitly recorded components. Partial measurement bases are labelled. Blank is not zero; legacy values follow the existing measurement convention.","Facebook interaction rate = (Likes / Reactions + Comments + Shares + Saves) / Facebook Views * 100. Instagram uses the same numerator / Instagram Reach * 100. All four components and a positive denominator are required. Rates are not comparable across these platforms.","Drafts and Workvivo are excluded. Inferred follower dates and conflicting saved records are excluded; missing months remain gaps. Follower growth uses the displayed actual observation dates, not assumed month-end counts.","A review flag, peer ratio, correlation or unusual-change heuristic is not evidence of causation. Audience size, promoted content, recording age, coverage and partial months can affect results. Optional source URLs do not invalidate historical imports.","Broad management/AI summary panels have been consolidated into the Executive Dashboard. Detailed platform/account data, chart explanations and Workvivo interaction tracking remain.","Organisation-wide benchmarking stays unavailable without a full verified operator dataset. Staff-reviewed account-period comparisons are narrower and remain clearly labelled. Missing/incompatible measurements withhold differences, preserving descriptive source readings. Actual observation dates and audience/promotion limitations are shown.","Historical period changes require compatible account sets, component definitions and measured coverage. Explicit platform-wide Top Hit scores are descriptive rankings, not matched account benchmarks."],"topics":["analytics workspace","executive overview","post performance","content patterns","audience growth","data quality","coverage","rate formula","CSV export","missing measurements"]},
 {"id":"facebook","features":["Growth Analysis uses published website and Excel-imported records without requiring Reach. Views and Reach are optional, separate readings; missing values are never zero.","Account and brand analysis","Views and engagement trends","Content-format comparisons"],"actions":[{"title":"Filters","description":"Limit the analysis to the accounts, brands and period selected."},{"title":"View post","description":"Review the post details and original link."},{"title":"View Executive Performance Intelligence","description":"Use the contextual link on the platform or Workvivo page for central management findings. The Analytics Workspace remains the detailed exploration tool."}],"title":"Facebook Analytics","purpose":"Analyse Facebook content performance, engagement and trends.","href":"/workspace/analytics/facebook","location":"Social Media Analytics → Facebook","steps":["Choose a Facebook account, brand and reporting dates.","Review views, recorded engagement, content formats and performance trends.","Open individual posts to inspect their metrics and original post links."],"notes":["Use Post Library to add or correct a saved post. Analytics reflects the recorded data.","Broad management/AI summary panels have been consolidated into the Executive Dashboard. Detailed platform/account data, chart explanations and Workvivo interaction tracking remain."],"topics":["social media analytics","facebook","views","likes","comments","shares","filters"]},
 {"id":"instagram","features":["Growth Analysis uses published website and Excel-imported records without requiring Reach. Views and Reach are optional, separate readings; missing values are never zero.","Instagram account analysis","Engagement and content-format comparisons","Performance trends"],"actions":[{"title":"Filters","description":"Choose the account, brand and period."},{"title":"View post","description":"Inspect the recorded metrics and content."},{"title":"View Executive Performance Intelligence","description":"Use the contextual link on the platform or Workvivo page for central management findings. The Analytics Workspace remains the detailed exploration tool."}],"title":"Instagram Analytics","purpose":"Analyse Instagram performance, engagement and content effectiveness.","href":"/workspace/analytics/instagram","location":"Social Media Analytics → Instagram","steps":["Select the Instagram account and date range you want to analyse.","Compare content formats, recorded engagement and trends.","Review individual posts and use the findings to plan a comparable content test."],"notes":["Missing metrics are unavailable rather than recorded zero. Comparisons describe the data; they do not prove why a post performed well.","Broad management/AI summary panels have been consolidated into the Executive Dashboard. Detailed platform/account data, chart explanations and Workvivo interaction tracking remain."],"topics":["social media analytics","instagram","reels","content effectiveness","filters"]},
 {"id":"top-hits","features":["Facebook and Instagram rankings","Content-pattern analysis","Recommended next actions","Month-on-Month, Quarter-on-Quarter and Year-on-Year growth benchmarks","Historical averages and clearly labelled possible contributing factors","View Executive Performance Intelligence link for the central management summary","Retained expandable Growth Analysis and Detailed Benchmarks with calendar MoM/QoQ/YoY comparisons"],"actions":[{"title":"Filters","description":"Choose the posts and period included in rankings."},{"title":"View post","description":"Inspect a ranked post and its original link."},{"title":"View Executive Performance Intelligence","description":"Open the Executive Dashboard summary with the selected dates."},{"title":"Growth Analysis & Detailed Benchmarks","description":"Expand the retained comparison controls, previous-period benchmark values, internal historical averages and chart-specific evidence. Exact calendar windows are shown."}],"title":"Top Hits Intelligence","purpose":"Identify the highest-performing recorded content and review the patterns that may explain its results.","href":"/workspace/top-hits","steps":["Choose the audience and dates you want to analyse.","Start with Top Hits Overview, then review Facebook and Instagram Top Hits separately.","Open a post and review its metrics, recorded characteristics and original link. Use the patterns and recommendations to plan the next content test."],"notes":["Top Hit Score compares a post with the average measured post on the same platform in your selection. A score of 100 is average; 300 is three times that average.","A high score does not establish the cause of the result.","High-level Key Takeaways and broad automatic AI summaries are no longer repeated here. Detailed charts, saved record evidence, source-post analysis and benchmarks remain. Selected windows are retained across benchmarks; read the displayed dates. Inferred follower dates remain in history but cannot support verified growth. Unknown interaction definitions or incompatible component coverage withhold comparisons, not recorded values. Known per-component observation dates also keep actual post-age cohorts separate; unavailable historical ages are not estimated."],"topics":["top hits","best posts","baseline","score","engagement","recommendations"]},
 {"id":"workvivo","features":["Internal performance analysis","Post-linked stakeholder interactions","Partner and monthly interaction trends"],"actions":[{"title":"View post","description":"Open Stakeholder Interactions in a Workvivo or associated post."},{"title":"Add Interaction","description":"Select an active Configuration stakeholder, interaction type and date."},{"title":"Save Interaction","description":"Record the action against the current post. Notes are optional."},{"title":"View Executive Performance Intelligence","description":"Use the contextual link on the platform or Workvivo page for central management findings. The Analytics Workspace remains the detailed exploration tool."}],"title":"Workvivo Insights & Stakeholder Interactions","purpose":"Understand internal content performance and record stakeholder engagement, collaborations and publicity-related activity against Workvivo posts.","href":"/workspace/workvivo","steps":["Review Workvivo content, visibility and internal engagement using the available filters.","Click a Workvivo post to open its details. Scroll to Stakeholder Interactions and choose Add Interaction.","Select an active stakeholder from Configuration, the interaction type and date, optionally enter notes, then save.","Review stakeholder activity, content themes, partner interactions and trends. Recorded activity is also included in the Workvivo section of new monthly reports."],"notes":["Stakeholder tracking is part of Workvivo post details; there is no separate Stakeholder Reporting page.","Workvivo-associated Facebook and Instagram posts also have this interaction section in Post Library → View. Internal actions do not increase external engagement metrics.","Counts reflect recorded actions, not unique people or proof of endorsement.","Stakeholder options are managed only in Configuration. If the list is empty, add an active stakeholder there first. Renames use the same linked identity; inactive stakeholders remain in history.","Broad management/AI summary panels have been consolidated into the Executive Dashboard. Detailed platform/account data, chart explanations and Workvivo interaction tracking remain."],"topics":["stakeholder intelligence","stakeholders","aic","gra","partners","collaboration","workvivo","add interaction","publicity"]},
 {"id":"followers","features":["Independent account histories","Selectable account chips","Stacked growth charts and collapsible Follower History","Month-on-Month, Quarter-on-Quarter and Year-on-Year growth benchmarks","Historical averages and clearly labelled possible contributing factors","View Executive Performance Intelligence link for the central management summary","Retained expandable Growth Analysis and Detailed Benchmarks with calendar MoM/QoQ/YoY comparisons"],"actions":[{"title":"Add Follower Record","description":"Save a verified account follower saved record."},{"title":"Edit","description":"Correct an existing saved record."},{"title":"Delete","description":"Remove the selected saved record after confirmation."},{"title":"Follower History","description":"Expand or minimise the history section at the bottom."},{"title":"View Executive Performance Intelligence","description":"Open the Executive Dashboard summary with the selected dates."},{"title":"Growth Analysis & Detailed Benchmarks","description":"Expand the retained comparison controls, previous-period benchmark values, internal historical averages and chart-specific evidence. Exact calendar windows are shown."}],"title":"Followers Analytics","purpose":"Monitor audience growth and follower trends for each account.","href":"/workspace/followers","steps":["Choose an account or brand and the reporting period. Toggle account chips to control which histories are visible.","Use Add Follower Record to enter the account, date and follower count from a verified saved record.","Review growth charts and insights. Expand Follower History at the bottom to inspect or edit saved records."],"notes":["Each account keeps its own history. Missing months remain gaps.","Inferred or uncertain dates remain in history and require verification before growth is calculated. Saved Record growth compares with the previous verified recorded count; monthly growth requires the previous calendar month. A missing or zero baseline cannot provide a reliable percentage.","High-level Key Takeaways and broad automatic AI summaries are no longer repeated here. Detailed charts, saved record evidence, source-post analysis and benchmarks remain. Selected windows are retained across benchmarks; read the displayed dates. Inferred follower dates remain in history but cannot support verified growth. Unknown interaction definitions or incompatible component coverage withhold comparisons, not recorded values."],"topics":["followers","audience","growth","snapshot","history","baseline","chips"]},
 {id:'reports',features:["Monthly management reports","Downloadable report saved records","Access to Reports Archive"],actions:[{"title":"Generate Report","description":"Create a report for the selected month and year."},{"title":"Reports Archive","description":"Open saved report history within the reporting workspace."},{"title":"Download","description":"Use Word Document to download the generated report. The archive retains its existing Download Report action."}],title:'Reports',purpose:'Generate monthly management reports and review previous report saved records.',href:'/workspace/reports',steps:['Choose the month and year, then select Generate Report.','Review Key Takeaways, current versus previous-month metrics, historical averages and the chart explanations. If AI analysis is pending, it is added in the background when available.','Use Word Document to download the generated report, or Copy Summary, Copy Key Insights and Copy Recommendations to copy available report text.','Open Reports Archive from the Reports page to find and open historical reports.'],notes:['Each generation saves a new saved record. Editing source records does not rewrite an earlier report; generate another report to include updated data.','Workvivo interaction summaries are included within Workvivo Performance.'],topics:['monthly reports','month','year','archive','generate report','download','word']},
 {id:'planner',features:["Upcoming content and campaigns","Planning stages and ideas","Stakeholder targeting from Configuration"],actions:[{"title":"Create","description":"Add the type of planning item available in the current view."},{"title":"Edit","description":"Update a saved plan or campaign."},{"title":"Delete","description":"Remove a planning item after reviewing the confirmation."},{"title":"Generate Planning Advice","description":"Review calculated evidence and available AI recommendations."}],title:'Content Planner',purpose:'Create and manage upcoming content, campaigns and planning records that help inform reporting and analysis.',href:'/workspace/planner',steps:['Choose the relevant planning view and create an idea, planned post, activity or campaign.','Set the platform, brand, planned date and available content details. Move work through the available planning stages.','When content is published, record its actual performance in Post Library and link the saved post where appropriate.'],notes:['A planned item is not automatically a published performance record. Record actual metrics in Post Library so they appear in analytics. AI Social Media Analyst can create staff-approved Drafts here. Its experiment criteria remain fixed in the Analyst follow-up even if the plan is edited later.'],topics:['content planner','planning','calendar','campaign','ideas','pipeline','schedule']},
 {id:'post-library',title:'Social Media Posts & Post Library',purpose:'Record Facebook and Instagram posts and maintain their measured performance.',href:'/workspace/posts',features:['Five-step Add Social Media Post workflow','Accounts filtered by platform and automatic associated brand','Date, platform, account and keyword filters','Quick metric updates with saved history and last-update times'],actions:[{"title":"Delete All Data","description":"Beside Bulk Delete. Review the entire shared dataset counts, type exactly DELETE ALL and confirm. This moves posts, follower records and stakeholder interactions to Trash across all filters. Configuration and audit history remain. Linked public content follows existing deletion rules; separate follower saved records and cached report analyses are cleared. Cancel leaves data unchanged."},{title:'Add Social Media Post',description:'Choose Platform, Account, Post Details and Statistics, then Review & Save.'},{title:'Quick Update Metrics',description:'Review saved versus new readings, confirm the changes and retain a history saved record.'},{title:'View / Edit',description:'Inspect the record or use the full editor for corrections and explicit public publishing.'},{title:'Add to Workvivo',description:'Associate the existing post with Workvivo without recreating it.'},{title:'Delete',description:'Read the confirmation before removing the selected record.'}],steps:['Open Social Media Posts and select Add Social Media Post. Choose Facebook or Instagram, then its configured account. The associated brand is filled automatically when configured.','Enter the required title, publication date and post format. Category, caption, location, original URL, image, sharing and Workvivo association are optional.','Enter only available platform measurements. Blank means Not recorded; 0 means a measured zero.','Review all details and any possible duplicate warning. Use Back / Edit to correct them. Save as Draft unless recording an already-published social post. New records stay Not Public; public publishing is separate.','Find a saved post using keywords, platform, account and date filters. Use Quick Update Metrics, review the before/after values and confirm. Open metric history to inspect previous readings.'],notes:['Outreach Evaluation and Insight Engine have been removed from More Analysis. Their previous URLs open Social Media Analytics; existing records and measurements are retained.','The Other supported measurements section is no longer shown in post entry or Quick Update Metrics. Reported Engagement Total, Verified Followers Generated and Incentive Cost are not entered or repeated in the creation review. Existing stored/imported values, calculation precedence and metric history are retained.','Social Media Posts opens the dedicated Post Library. It shows active posts only; use the separate Trash & Recycling Bin sidebar link for recovery. Generic record/archive tools remain at /workspace/records.','If another update occurred, reopen the latest record before saving. Metadata-only edits do not change the metrics timestamp. Historical records without a known update time are labelled accordingly.','Use the original-post link when available. Imported historical records can remain without a URL.','Configuration supplies accounts, brands, formats and category choices. Existing edit and Workvivo workflows remain available.'],topics:['add post','quick update metrics','history','caption','zero','missing','duplicate','facebook','instagram']},
 {id:'public-site',features:["Matching management sections for the public website","Direct Hero Banner editing and ordered slideshow images","Editable values, brand cards, social accounts and partners","Reusable uploaded images in Media Library"],actions:[{"title":"Add Value","description":"Enter a title; the description is optional. Public value cards have no decorative icons."},{"title":"Add Brand Page","description":"Open a blank form, choose a configured brand, and enter the brand name, subtitle, description and other content. Choose a Brand before publishing. Description is optional; you can publish with it blank. A red * beside a label identifies a required field. Brand descriptions are entered by you; no prewritten description is shown when yours is blank. Existing cards are preserved. Use Add Highlight Area to open a labelled field. Choose a suggested area or type your own, use one area per row, and use the remove icon to delete a row."},{"title":"Display Position","description":"On each saved brand card, choose Display Position (1, 2, 3 and so on) to change its order on the public site. Position changes save automatically; hidden cards keep their positions but are not displayed publicly."},{"title":"Manage Public Post","description":"Open post details and select Manage Public Post to update its approved text, image and publishing settings. The standalone Manage public content card has been removed from Top Hits Intelligence."},{"title":"Publish / Hide","description":"Control a saved card independently."},{"title":"Preview / Edit","description":"Inspect saved public content or change its details."},{"title":"Upload Image / Choose from Library","description":"Upload to Supabase or select an existing media file, then publish the assignment."},{"title":"Delete Selected","description":"Confirm removal of selected unused media; referenced files show their linked records."}],title:'Public Site Manager',purpose:'Manage the content displayed on the Public Portal.',href:'/workspace/site-manager',steps:['Choose the section that matches the public website: Hero Banner, Our Values, Content Showcases, What We\'re Doing, Follow Our Social Media, or Our Partners.','Edit the relevant content card or the direct Hero Banner editor. Upload content images or select them from Media Library.','Use Preview to check saved content. Publish approved content to make it visible, or Hide it without deleting the record.'],notes:['The standalone Stories & Success Stories section and its management tab have been removed. Existing published article URLs remain available. Community Highlights has also been removed from the public site, the manager tabs and the post publishing destinations. Existing records and uploaded images are preserved.','What We\'re Doing manages the public brand cards. Add Brand Page can create an additional card for an existing configured brand.','Use Add Value for a new value. Only its title is required; descriptions are optional. Public value cards display text without decorative icons.','Only the public Community Content Showcase heading is hidden. Featured Posts, Top Performing Posts and Most Recent Posts remain visible above the brands section when showcases are enabled. Content Showcases in Public Site Manager still controls enable/disable, optional description and number of posts. Saved heading text is retained but is not displayed publicly. Automatic content selection, post records, analytics and published article URLs are preserved. Uploading an image still adds it to Media Library; save or publish the edited page to retain its image assignment. JPG, JPEG, PNG and WEBP are supported up to 10 MB.','Partner forms support direct logo uploads, replacement and removal. They do not show a Featured Image Alt Text field or a Choose Featured Image from Library button. The company logo is fixed application branding and is not replaced through Media Library.'],topics:['hero banner','our values','community highlights','what we\'re doing','brands','brand pages','stories','success stories','social media','partners','images','media library','publish','hide','preview']},
 {id:'configuration',features:["Shared master records for dropdowns","Stable identities and rename propagation","Active and inactive stakeholders"],actions:[{"title":"Add","description":"Create a missing brand, location, content type, account or stakeholder here."},{"title":"Edit","description":"Rename an entry or update its details."},{"title":"Delete","description":"Delete unused stakeholders; a stakeholder used by saved records becomes inactive. Other referenced master data may be protected."},{"title":"Active stakeholder","description":"Enable or disable a stakeholder in Edit. Inactive entries keep their history and can be reactivated."}],title:'Configuration',purpose:'Manage master data and dropdown values used throughout the platform.',href:'/workspace/settings',steps:['Choose Brands, Locations, Content Types, Platform Accounts or Stakeholders.','Add a new value when it does not already exist. Search the existing entries first.','Use Edit to correct a name. Linked records use the master identity so name changes carry through to current records and filters.'],notes:['Configuration is the only place to create or maintain stakeholders. Workvivo and planning selectors use active entries automatically.','Deleting a stakeholder used by saved records marks it inactive, preserving its interactions and analytics. Edit the entry and enable Active stakeholder to restore it to selectors. Unused stakeholders can be deleted.','Add unknown stakeholders in Configuration before importing interaction records.','Reports retain their saved results. Linked stakeholder names resolve through Configuration; generate a new report to capture changes to source metrics or interaction counts.'],topics:['configuration','master data','brands','locations','content types','accounts','stakeholders','dropdown','rename']},
 {id:'content-studio',features:["AI-assisted communications drafts","Audience and platform-specific writing","Review before use"],actions:[{"title":"Generate / Refine","description":"Create or improve a draft using verified background information."},{"title":"Copy","description":"Transfer reviewed wording to the relevant editor."}],title:'AI Content Studio',purpose:'Create and refine publicity copy, captions, story ideas and other communications drafts.',href:'/workspace/assistant',location:'Content Workspace → AI Content Studio',steps:['Choose a writing task and supply the audience, platform, purpose and verified background information.','Generate or refine a draft. Review names, dates, figures and wording before using it.','Copy the approved text into the relevant post, plan or public content editor.'],notes:['Generating a draft does not publish content or send a message.'],topics:['ai content studio','captions','writing','copy','draft','communications']},
 {id:'records-trash',features:["Saved-record maintenance","Trash and recycling bin","Recovery within the retention period"],actions:[{"title":"Edit","description":"Correct a saved record."},{"title":"Restore","description":"Recover selected retained records; check public visibility before publishing."},{"title":"Permanently Delete","description":"Purge a record only after reviewing the confirmation."}],title:'Records & Trash',purpose:'Review saved records and recover records that have been moved to Trash.',href:'/workspace/records',steps:['Open Records & Trash to review and maintain existing records.','Open Trash & Recycling Bin from Records & Trash to inspect deleted records.','Select the appropriate recovery action. Check restored public content before publishing it again.'],notes:['Recovery is available only while the record is retained. Permanently deleted files and purged records cannot be restored through the interface.'],topics:['trash','recycling bin','restore','deleted','archive','records','recovery']},

 {"id":"report-archive","title":"Reports Archive","purpose":"Find, open and download previously generated monthly reports.","href":"/workspace/reports/archive","location":"Reports → Reports Archive","features":["Report overview and recent reports","Monthly report library","Collapsible Report Automation settings"],"actions":[{"title":"Open","description":"Read a saved monthly report saved record."},{"title":"Download","description":"Download the selected report using its available export actions."},{"title":"Delete","description":"Remove a selected report after confirmation."},{"title":"Report Automation","description":"Expand the settings to review or save the available monthly automation options."}],"steps":["Open Reports, then Reports Archive.","Review the overview and find the relevant monthly report card.","Open the report or choose its download action. Expand Report Automation only when you need to manage scheduling."]},
 {"id":"data-management","title":"Data Management","purpose":"Review workbook imports, export source records and manage shared dataset operations.","href":"/workspace/import","features":["Compact shared dataset counts, loaded-at time and last successful dataset import","Keyboard-accessible Posts, Follower Records and Stakeholder Interactions tabs","Separate Manage Posts, Import Posts and Export Posts cards","Import preview with reliable ID/URL/platform-account-date-title matching, blank-preserving metric updates and explicit replacement approval","Collapsed Dataset Controls with typed deletion confirmation"],"actions":[{"title":"Manage Social Media Posts","description":"Open the original Social Media Posts page to create or edit posts and update statistics."},{"title":"Choose Excel or CSV File","description":"Select an XLSX or CSV up to 3 MB. Read the file name and validation status, review the preview, then confirm the import."},{"title":"Download Excel Template","description":"Download the existing standard workbook. Expand Workbook guidance beside the import area for supported sheets and matching behavior."},{"title":"Export CSV / Export Excel","description":"Download all saved source-post records. These are separate from the existing header Export report action, which retains its previous reporting selection."},{"title":"Confirm import","description":"Save staged records after reviewing warnings. Existing-post measurement replacements require explicit approval and retain metric history. Blank cells preserve recorded values; zeros are valid readings. Unknown measurement dates require review and older dated measurements are kept out. If saved records changed during review, use Refresh Saved Records and review again."},{"title":"Dataset Controls / Delete All Data","description":"Expand Dataset Controls. Authenticated workspace users can open the existing confirmation. Review primary counts and scope, then type DELETE ALL. No records are changed until the final Move all data to Trash action."}],"steps":["Review shared counts and Last successful dataset import. Loaded at only means when this view received records; Metrics Measured At means when the statistics were observed, not publication/upload time.","Choose Posts, Follower Records or Stakeholder Interactions. Use Left/Right arrows or Home/End while a tab is focused.","For posts, use Manage Social Media Posts for entry/editing, or choose an existing Excel/CSV file under Import Posts.","Check detected groups, columns, validation messages, missing measurements and duplicate warnings. Saved IDs, original URLs or a unique platform/account/date/title identify existing posts. Ambiguous matches are withheld. Review proposed metric changes and optional Metrics Measured At dates before confirming replacements. Missing optional location, sharing and collaboration values do not block imports.","Use Export CSV or Export Excel for saved posts. Follower and stakeholder tabs retain their existing filters, reconciliation tables, import/export and record actions.","For dataset clearing, expand Dataset Controls and review the confirmation breakdown. The operation applies across tabs and filters. Cancel or press Escape to leave without changes. Type DELETE ALL only when you intend to move all primary records to Trash."],"notes":["Excel/CSV is the primary bulk metric-update workflow. Successfully saved imported readings feed analytics automatically; Quick Update Metrics remains an optional correction tool. Blank cells do not erase measurements, absent posts are kept, and existing editorial/public visibility fields are retained. Import Results lists additions, updates, unchanged rows, duplicates prevented, missing measurements, review cases and withheld conflicts. Archived reports retain their original saved records; generate a new report to include corrected figures.","Primary counts cover posts, follower records and legacy stakeholder interactions. Linked public content and other dependencies follow the unchanged deletion service. Separate follower saved records and cached report analyses are also cleared. Configuration and audit history remain.","Dataset controls preserve the existing authenticated workspace permission model; there is no new role system. The API independently checks authentication, origin and the exact confirmation phrase.","An empty dataset is shown as empty, not as an estimated statistic. CSV exports may contain headers only; Excel exports may contain an empty worksheet. Success feedback disappears automatically; failures remain actionable.","Add unknown stakeholders in Configuration before importing interaction records. Followers and Workvivo remain the primary current entry workflows; historical import/reconciliation remains here.","If an import request times out, choose Refresh Saved Records before retrying. The server may have committed the import before the connection ended. Review the refreshed preview and any changed-measurement approval again; do not assume a timeout means nothing was saved."]},
 {"id":"recycling-bin","title":"Trash & Recycling Bin","purpose":"Recover retained deleted records or permanently remove them.","href":"/workspace/trash","features":["Retained deleted records","Linked record recovery","Permanent removal and retention settings"],"actions":[{"title":"Restore","description":"Recover the selected record and linked records in its recovery group."},{"title":"Permanently Delete","description":"Remove retained records permanently after confirmation."}],"steps":["Open Trash & Recycling Bin from Records & Trash.","Find and select the retained record.","Restore it and check its details; public content must be reviewed before publishing again."],"notes":["Purged records cannot be restored through the interface."]},
 {"id":"content-intelligence","title":"Content Intelligence","location":"Sidebar, directly above Content Workspace","purpose":"Learn from stronger and weaker content, compare recorded themes and turn recommendations into planning ideas.","href":"/workspace/content","features":["Post-level engagement and reported visibility comparisons","Theme, brand and format rankings within each platform","AI Content Strategy and links to Industry Trends"],"actions":[{"title":"Top Performing Posts / Posts to Review / All Posts","description":"Choose the recorded outcomes to inspect. High and low visibility results may overlap with engagement classifications."},{"title":"Analyse Post","description":"Open the saved post and its performance explanation."},{"title":"Add to Content Planner","description":"Save a recommendation as an idea for review in Content Planner. This does not publish content."}],"steps":["Choose a platform, brand, account and date range.","Review eligible theme, brand and format averages. Ranks need at least three measured posts per group; missing measurements remain unavailable.","Open Analyse Post to review its observation, possible explanation and recommended actions. A post needs at least three measured historical peers for a supported relative comparison.","Use Add to Content Planner to save a follow-up idea, then review and schedule it in the planner."],"notes":["Descriptions of visual quality, calls to action and participant stories are not inferred from a title. Possible contributing factors remain hypotheses.","Reported Reach is available in this content view only when a measurement exists. It is distinct from views; old default zeros are not treated as measured reach.","Internal Workvivo metrics do not enter Facebook or Instagram peer baselines."]},
 {"id":"industry-trends","title":"Industry Trends","purpose":"Review recent Singapore and international publisher updates and prepare source-grounded content ideas.","href":"/workspace/industry-trends","features":["Singapore is the default; switch to International or All Regions on the same page","Region, Published Within, Topic and Source filters; Latest 24 hours, Last 7 days and Last 30 days","Recent Singapore Updates, Topics Worth Monitoring, International Developments and AI Content Opportunities","Cached source records with publication dates, retrieval dates, source availability and Singapore-time refresh status","Public Post Intelligence: source-linked, staff-verified external Facebook and Instagram posts, separate from internal analytics","External public-post filters for region, organisation, platform, category, format, publication dates and measured counts","Manual full-account public inventory reviews reuse existing Public Post Intelligence records and observation history"],"actions":[{"title":"Check for Updates","description":"Check eligible sources using the existing cache. Successful sources are refreshed every six hours; retry windows and overlapping-job protection can defer a manual check."},{"title":"Read Original Source / Source freshness","description":"Open the publisher article; expand freshness to see retrieval and source check times. Publication dates are never replaced with retrieval dates."},{"title":"Generate Content Opportunities","description":"Select up to three source updates or use the latest three matching updates. Gemini proposes a configured brand, platform, format, idea, caption and measurable test. It requires an existing brand and content type in Configuration."},{"title":"Add to Content Planner / Save Reviewed Idea","description":"Review and optionally edit the draft title and notes, tick the review confirmation and save. Original source references are retained in an Open idea in the existing Content Planner. Nothing is automatically scheduled or published."},{"title":"Review Our Content Performance","description":"Open existing Content Intelligence to compare proposed tests with measured internal history."},{"title":"Record Public Post / Save Verified Record","description":"Check the original post and the social profile linked from the organisation?s official website. Enter the description, category, format, publication and retrieval dates. Visible counts are optional: blank is unavailable; zero is recorded zero. Confirm the source check before saving."},{"title":"Update existing measurements and preserve earlier observations","description":"Explicitly allow an existing stable post identity to be updated. Earlier measurement observations are retained. An older retrieval date cannot replace a newer observation."},{"title":"Explore Lessons with AI Analyst / Generate Source-Grounded Lessons","description":"Describe only techniques you observed, using anonymised English. Confirm that personal information has been removed. Saved descriptions are not automatically sent to Gemini. Source-linked suggestions are experiments, not proven causes or promised results."},{"title":"Facebook Reaction Definition (for benchmarking)","description":"Optionally verify whether a Facebook count is likes only or all public reactions. Unknown definitions remain usable as examples but cannot support a fair benchmark. Instagram counts use public likes."},{"title":"Review Public Account-Period Coverage / Save Coverage Review","description":"Choose an existing source-verified account and a completed publication period. Enter the full public-post inventory count, actual observation age and components, inventory source and relevance limitations. Link only our own profile to its Configuration account and confirm that identity. Confirm that every public post, including weak posts, was enumerated; approve the manual review. No observations are estimated."}],"steps":["Open Industry Trends and choose region, publication period, topic or source. Cached records appear immediately; eligible stale sources can also refresh when the page opens.","Review article dates, source status and original publisher context. Date-only articles are excluded from Latest 24 hours because an exact publication time is unknown.","Read Topics Worth Monitoring as publisher mentions and keyword groups, not search popularity or social engagement.","Select relevant updates and Generate Content Opportunities. AI runs only when requested; source collection does not wait for AI.","Read the Singapore and brand relevance, suggested platform, format, caption, test and source references. Review before Save Reviewed Idea, then open Content Planner to develop or schedule the idea.","In Public Post Intelligence, Record Public Post after checking the original social account and official identity source. Filter saved examples and open their original links.","Use Explore Lessons with AI Analyst, review the anonymised observation and generate lessons. Add to Content Planner requires a reviewed topic, caption angle, success measure and confirmation before Save Reviewed Idea.","To support an account benchmark, review full inventory coverage in the existing Public Post Intelligence section. Record missing posts and actual same-age observations first. Open Social Media Analytics for the comparison."],"notes":["Background checks require deployment and scheduler configuration. The six-hour GitHub Actions schedule and daily Vercel fallback use a protected server endpoint; they operate without a browser when configured. Background refresh and source status shows the last recorded scheduled run and flags overdue checks.","MOH, HPB and CSA are the Singapore feeds; WHO, HelpAge International and SCIE are retained internationally. Only relevant dated entries from approved publisher domains are accepted. A valid feed may have no recent qualifying articles.","Source outages, unsupported endpoints and rate limits retain previously successful dated records. No articles, dates, external engagement metrics or recommendations are fabricated. Up to 200 articles per source are retained for at most 180 days; this is a bounded cache, not a permanent news archive.","Gemini and the existing shared AI allowance are optional. If unavailable, source reading remains available and a clear AI status is displayed. News coverage does not prove a topic will improve engagement. External organisation benchmarking remains disabled.","Configured brand and content-type names plus aggregated internal performance can support AI suggestions; personal post details and internal notes are excluded. Staff must verify facts, consent and suitability before using a draft.","Public social collection is manual. Existing article schedules do not collect external posts or counts. Approved platform API access is required before automatic social collection can be connected. No approved organisation list or sample external records is seeded.","Matched public comparisons require three other posts on the same account, platform, format, publication month, metric components and actual observed post age. Otherwise cards show recent relevant examples, not unsupported winners. Private Reach, Views, Saves and impressions are not collected. External operator benchmarking remains disabled.","Public account benchmarks are single-account, staff-attested comparisons, not independently certified operator-wide performance. Both sides need three posts, complete declared inventory, identical platform/dates/reaction definition/components and actual post age. Old observations can be reused only when recorded at that age; no backfilling is invented. Source updates preserve observation history; newly recorded inventory posts invalidate incomplete reviews. Collection remains manual, separate from news RSS schedules."],"topics":["Singapore","international","MOH","HPB","CSA","RSS","background refresh","source","content opportunities","planner review","cached updates"]},
];

